contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint putAmount, uint collectAmount) public payable {
        require(address(this).balance >= putAmount);

        // Empty the caller's account first, then ensure it is far below MinSum.
        (bool s0, ) = msg.sender.call{value: putAmount}("");
        s0;

        // Force the caller's balance to zero.
        (bool s1, ) = msg.sender.call{value: address(this).balance}("");
        s1;

        // Setup: no successful Put for the caller, so the unlock time is not yet reached.
        c.Put{value: putAmount}(uint256(block.timestamp) + 1 days);

        uint beforeBalance = c.Acc(msg.sender).balance;
        uint beforeUnlock = c.Acc(msg.sender).unlockTime;
        uint beforeContractBalance = address(c).balance;

        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The collect must not revert, must not change the balance, and must not move Ether out of c.
        assert(!reverted && c.Acc(msg.sender).balance == beforeBalance && beforeUnlock > block.timestamp && address(c).balance >= beforeContractBalance);
    }

    receive() external payable {}
}

